#!/bin/bash
CONTENT=""

TOKEN=$(cat /root/.config/gh/hosts.yml 2>/dev/null | grep oauth_token | head -1 | sed 's/.*oauth_token: //')

curl -s -X PUT \
  -H "Authorization: token $TOKEN" \
  -H "Content-Type: application/json" \
  "https://api.github.com/repos/diogommatos15-glitch/novo-app/contents/src/app/layout.tsx" \
  -d "{\"message\":\"fix: remove lasy-bridge.js that crashes Vercel build\",\"content\":\"$CONTENT\",\"sha\":\"a902e4d6da0f27a412d873018928194a30220acb\"}" \
  -o /workspace/push_result.json

echo "Done"
